package omi.cme.globex.ilink3.sbe.v8_5.enums;

import java.util.Optional;

/**
 * Indicates if order was sent manually or generated by automated trading logi
 *
 * <p>Backed by short. Values correspond to the wire integer encoding.</p>
 */
public enum ManualOrderIndicatorOptional {

    /**
     * Indicates if order was sent manually or generated by automated trading logi
     */
    NO_VALUE((short) 255, "Indicates if order was sent manually or generated by automated trading logi"),

    /**
     * Automated
     */
    AUTOMATED((short) 0, "Automated"),

    /**
     * Manual
     */
    MANUAL((short) 1, "Manual");

    private final short wire;

    private final String description;

    ManualOrderIndicatorOptional(short wire, String description) {
        this.wire = wire;
        this.description = description;
    }

    /**
     * Returns this value's encoding on the wire.
     *
     * @return the wire value
     */
    public short wire() {
        return wire;
    }

    /**
     * Returns the description the protocol specification gives this value.
     *
     * @return the description
     */
    public String description() {
        return description;
    }

    /**
     * Returns the value with the given wire encoding.
     *
     * @param wire the encoding read from the wire
     * @return the matching value, or empty when the protocol declares no value for it
     */
    public static Optional<ManualOrderIndicatorOptional> fromWire(short wire) {
        return switch (wire) {
            case 255 -> Optional.of(NO_VALUE);
            case 0 -> Optional.of(AUTOMATED);
            case 1 -> Optional.of(MANUAL);
            default -> Optional.empty();
        };
    }
}
